var sb = new System.Text.StringBuilder();
sb.Append("isPlaying=" + UnityEditor.EditorApplication.isPlaying).Append("\n");
sb.Append("isPlayingOrWillChangePlaymode=" + UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode).Append("\n");
var stage = UnityEditor.SceneManagement.PrefabStageUtility.GetCurrentPrefabStage();
sb.Append("prefabStage=" + (stage == null ? "(none)" : stage.assetPath)).Append("\n");
var sc = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
sb.Append("activeScene=" + sc.name + " roots=" + sc.rootCount).Append("\n");
var panels = UnityEngine.Object.FindObjectsOfType<MonoBehaviour>(true);
int n = 0;
foreach (var mb in panels) { if (mb != null && mb.GetType().Name == "SaveSlotPanel") n++; }
sb.Append("SaveSlotPanel instances=" + n).Append("\n");
return sb.ToString();
